INSERT INTO sync_daily_summaries (lead_id, date, summary) VALUES
  ('df4d59d7-de59-4bbc-93a3-7b09bcc13e80', '2026-10-19', $q$Nomor dikonfirmasi benar; setelah perkenalan riset, dijawab "nanti kami kabari". Kami minta dikabari jika ada informasi terbaru.$q$),
  ('fcd5b660-a44b-4f18-8970-1aac4d240add', '2026-10-19', $q$Nomor benar (dokter ada jam 17.30). Setelah perkenalan mereka menanyakan dari mana dan perusahaan apa; kami jelaskan dari startup Sahaibat. Belum ada balasan lanjutan.$q$),
  ('7b4edd32-2912-4fdb-b857-4d3d86a537c6', '2026-10-19', $q$Nomor benar (praktik dr. Surya) dan kami kirim perkenalan riset. Belum ada balasan.$q$),
  ('4efdac02-990c-46e1-92e1-92a9ea4c8bdf', '2026-10-19', $q$Customer care menjawab bahwa penelitian akan dikonfirmasi dulu, lalu memberikan kontak lain (Kak Rizka) untuk urusan penelitian. Kami berterima kasih dan mengonfirmasi nomor kontak tersebut; belum ada balasan.$q$),
  ('70db794a-12e6-4a15-8b0c-f95571971603', '2026-10-19', $q$Admin memberikan nomor HRD (Bu Rosa) untuk tindak lanjut; kami menghubungi nomor HRD tersebut dan mengirim perkenalan riset. Belum ada balasan dari HRD.$q$),
  ('aba1a0be-5706-422a-9adc-eadb603812b1', '2026-10-19', $q$Kami melanjutkan komunikasi kemarin dan melampirkan surat resmi. Belum ada balasan.$q$),
  ('30e75f34-2c54-4353-ba49-116e732a736e', '2026-10-19', $q$Setelah balasan otomatis, nomor dikonfirmasi; mereka menanyakan apakah riset untuk tugas kuliah, lalu kami jelaskan dari startup Sahaibat. Belum ada balasan lanjutan.$q$),
  ('5b689a68-00d6-420a-aefa-7d7997572fbc', '2026-10-19', $q$Pertemuan Google Meet jam 13.00 berlangsung; mereka mengirim data kredensial integrasi (tidak dicatat di sini). Sore hari kami membahas update inventory massal, mengirim dokumen MoU, dan menyampaikan rencana komersial (berbayar). Mereka mengirim beberapa pesan tanpa teks.$q$),
  ('e7178a0f-0468-4d8e-91ca-261d5a49a2de', '2026-10-19', $q$Mereka mengonfirmasi "iya mas"; kami melanjutkan diskusi kemarin. Belum ada balasan.$q$),
  ('b6433556-648c-4243-8747-2d1aff1369e3', '2026-10-19', $q$Kami menyampaikan surat sudah dikirim via email; admin membalas "baik terima kasih atas informasinya".$q$),
  ('04e82c65-fe8d-4b58-9d68-b34514594da9', '2026-10-19', $q$Pagi membenarkan nomor klinik Widya Husada; sore kami kirim perkenalan riset. Belum ada balasan.$q$),
  ('eb7b7ebf-02d6-49ee-bf9f-da48ed35892a', '2026-10-19', $q$Setelah perkenalan, menjawab belum bisa membantu untuk sementara. Atas pertanyaan kami, rekam medis sudah digital tetapi nama ERM tidak diketahui.$q$),
  ('e586cd3d-598e-4baa-b4d1-ee88dd98049f', '2026-10-19', $q$Dokter menyarankan menghubungi admin; kami menghubungi nomor admin, yang membalas otomatis bahwa itu nomor admin 24 jam dan menyarankan menghubungi klinik cabang terdekat.$q$),
  ('ba8de637-383a-4461-9879-fcd50d7dac1c', '2026-10-19', $q$Dokter mengirim email dan meminta maaf lupa; kami berterima kasih dan bertanya soal rekam medis praktik mandiri. Sore dijawab oleh perawat/pendaftaran (bukan dokter) dengan pesan singkat.$q$),
  ('1ba5456d-2f6b-4357-9f32-3213f46691fe', '2026-10-19', $q$Dokter awalnya kurang paham; mengaku rekam medis pakai kertas dan digital, catatan pasien "rahasia". Setelah kami jelaskan dan tawarkan online meeting Rabu, dijawab "iya/oke", lalu menanyakan profil perusahaan; kami jelaskan Sahaibat dan dijawab "Oke".$q$),
  ('ae42dfbe-32aa-40f5-869e-8579b9b33b0b', '2026-10-19', $q$Setelah perkenalan, mereka menanyakan lembaga riset, surat riset, dan asal pendidikan; kami jelaskan dari startup Sahaibat dan melampirkan surat. Belum ada balasan.$q$),
  ('acedf948-2158-41d7-9900-a2ec5d878868', '2026-10-19', $q$Kami menanyakan konfirmasi nomor; belum ada balasan.$q$),
  ('f530f108-8467-40ef-924f-66978f5d7f6a', '2026-10-19', $q$Nomor dikonfirmasi benar dan kami kirim perkenalan riset. Belum ada balasan.$q$),
  ('45478cb8-ef44-4f2f-931f-27dfbc003824', '2026-10-19', $q$Atas pertanyaan kami soal jangkauan home visit, dijawab maksimal 12 km.$q$),
  ('23c10c1e-ccbc-4ca4-bae0-0a4e94c9dedf', '2026-10-19', $q$Kami minta maaf baru menjawab, merumuskan jawaban atas pertanyaannya dan melampirkan surat. Belum ada balasan.$q$),
  ('bd07de06-c408-4492-a0d9-1f930d240b17', '2026-10-19', $q$Staf meminta diwakili bidan/dokter obgyn (kami: boleh bidan), akan izin ke dokter; menanyakan tujuan riset dan keuntungan bagi klinik. Kami jelaskan Sahaibat dan manfaat AI rekam medis; menunggu konfirmasi dokter.$q$),
  ('48f3d2ad-d111-413f-a166-b9aa94fbe9ea', '2026-10-19', $q$Pihak klinik akan konfirmasi dan meminta proposal; kami lampirkan surat permohonan. Mereka lalu memberi tahu status berubah menjadi RS (Bambang Shita Hospital, FKRTL) sehingga kemungkinan tidak masuk cakupan riset klinik; kami berterima kasih.$q$),
  ('6f9ba1f3-6c14-4d8b-9b94-7781cebe7b95', '2026-10-19', $q$Setelah balasan otomatis, nomor dikonfirmasi benar; kami kirim perkenalan riset. Belum ada balasan.$q$)
